const { chromium } = require('/tmp/probe/node_modules/playwright-core');
const { PNG } = require('/tmp/probe/node_modules/pngjs');
const { openApp } = require(process.cwd() + '/tests/web/mock.cjs');
const exe = process.env.CHROME_BIN;
const SECT = 16;
function analyse(buf, box, scale) {
  const png = PNG.sync.read(buf);
  const pad = { x: 12, y: 16 };
  const hw = box.w / 2, hh = box.h / 2, r = box.radius || 24;
  const ring = Array.from({ length: SECT }, () => ({ n: 0, c: 0, l: 0 }));
  const glow = { n: 0, l: 0 };
  const tag = { n: 0, c: 0 };
  for (let py = 0; py < png.height; py++) for (let px = 0; px < png.width; px++) {
    const sx = px / scale - pad.x, sy = py / scale - pad.y;
    const qx = Math.abs(sx - hw) - (hw - r), qy = Math.abs(sy - hh) - (hh - r);
    const d = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
    const i = (py * png.width + px) * 4;
    const R = png.data[i], G = png.data[i + 1], B = png.data[i + 2];
    const chroma = (Math.max(R, G, B) - Math.min(R, G, B)) / 255, lum = (0.2126 * R + 0.7152 * G + 0.0722 * B) / 255;
    if (Math.abs(d) <= 1.8) {
      const ang = Math.atan2(sy - hh, sx - hw); // -pi..pi, 0 = right
      const s = Math.floor(((ang + Math.PI / 2 + 2 * Math.PI) % (2 * Math.PI)) / (2 * Math.PI) * SECT); // 0 = top, clockwise
      ring[s].n++; ring[s].c += chroma; ring[s].l += lum;
    } else if (d > 2.5 && d < 14) { glow.n++; glow.l += lum; }
    if (sx > 18 && sx < 110 && sy > -11 && sy < 9) { tag.n++; tag.c += chroma; }
  }
  return { ring: ring.map((s) => (s.n ? s.c / s.n : 0)), ringL: ring.map((s) => (s.n ? s.l / s.n : 0)), glow: glow.n ? glow.l / glow.n : 0, tag: tag.n ? tag.c / tag.n : 0 };
}
(async () => {
  const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  for (const theme of ['dark', 'light']) {
    const init = 'try{localStorage.setItem("inhouselearn.theme","' + theme + '")}catch(_){}';
    const { page } = await openApp(browser, { viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, colorScheme: theme }, { init });
    const box = await page.evaluate(() => { const el = document.querySelector('.composer-shell'); const r = el.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, radius: parseFloat(getComputedStyle(el).borderTopLeftRadius) }; });
    const clip = { x: box.x - 12, y: box.y - 16, width: box.w + 24, height: box.h + 32 };
    const base = analyse(await page.screenshot({ clip }), box, 2);
    await page.click('#model-menu-btn');
    await page.waitForSelector('[data-thinking-level="ultra"]');
    await page.waitForTimeout(500);
    const t0 = Date.now();
    await page.click('[data-thinking-level="ultra"]');
    const frames = [];
    for (let k = 0; k < 14; k++) { const png = await page.screenshot({ clip }); frames.push({ t: Date.now() - t0, a: analyse(png, box, 2) }); }
    await page.waitForTimeout(1800);
    const steady = analyse(await page.screenshot({ clip }), box, 2);
    const info = await page.evaluate(() => ({ popupHidden: document.getElementById('model-menu-popup').classList.contains('hidden'), tag: !!document.querySelector('.ultra-tag'), mode: document.querySelector('.composer-shell').dataset.ultra, sweep: !!document.querySelector('.ultra-sweep'), tagRect: (() => { const r = document.querySelector('.ultra-tag').getBoundingClientRect(); const s = document.querySelector('.composer-shell').getBoundingClientRect(); return [Math.round(r.x - s.x), Math.round(r.y - s.y), Math.round(r.width), Math.round(r.height)]; })() }));
    console.log('\n=== ' + theme + ' · composer ' + Math.round(box.w) + 'x' + Math.round(box.h) + ' r' + box.radius + ' · base glow lum ' + base.glow.toFixed(3) + ' tag chroma ' + base.tag.toFixed(3));
    console.log('sector chroma delta (0-9, top clockwise, 16 sectors)  [glow lum delta ×100 | tag chroma ×100]');
    const row = (a) => a.ring.map((c, i) => Math.max(0, Math.min(9, Math.round((c - base.ring[i]) * 12)))).join('');
    frames.forEach((f) => console.log(String(f.t).padStart(5) + ' ms  ' + row(f.a) + '   [' + ((f.a.glow - base.glow) * 100).toFixed(1).padStart(5) + ' | ' + (f.a.tag * 100).toFixed(1).padStart(5) + ']'));
    console.log('steady    ' + row(steady) + '   [' + ((steady.glow - base.glow) * 100).toFixed(1).padStart(5) + ' | ' + (steady.tag * 100).toFixed(1).padStart(5) + ']  ring chroma avg ' + (steady.ring.reduce((a, b) => a + b, 0) / SECT).toFixed(3) + ' vs base ' + (base.ring.reduce((a, b) => a + b, 0) / SECT).toFixed(3));
    console.log(JSON.stringify(info));
    await page.screenshot({ path: '/tmp/probe/' + theme + '-steady.png' });
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
